struct spdk_single_ioviter {
	struct iovec	*iov;
	size_t		iovcnt;
	size_t		idx;
	size_t		iov_len;
	uint8_t		*iov_base;
};

struct spdk_ioviter {
	uint32_t	count;

	union {
		struct spdk_single_ioviter iters_compat[2];
		struct spdk_single_ioviter iters[0];
	};
};

struct spdk_iov_xfer {
	struct iovec *iovs;
	int iovcnt;
	int cur_iov_idx;
	size_t cur_iov_offset;
};

struct spdk_log_opts {
	/**
	 * The size of spdk_log_opts according to the caller of this library is used for ABI
	 * compatibility.  The library uses this field to know how many fields in this
	 * structure are valid. And the library will populate any remaining fields with default values.
	 * New added fields should be put at the end of the struct.
	 */
	size_t			size;
	spdk_log_cb		*log;
	spdk_log_open_cb	*open;
	spdk_log_close_cb	*close;
	void			*user_ctx;
};

enum spdk_log_level {
	/** All messages will be suppressed. */
	SPDK_LOG_DISABLED = -1,
	SPDK_LOG_ERROR,
	SPDK_LOG_WARN,
	SPDK_LOG_NOTICE,
	SPDK_LOG_INFO,
	SPDK_LOG_DEBUG,
};

struct spdk_log_flag {
	TAILQ_ENTRY(spdk_log_flag) tailq;
	const char *name;
	bool enabled;
};

struct spdk_json_object_decoder {
	const char *name;
	size_t offset;
	spdk_json_decode_fn decode_func;
	bool optional;
};

struct spdk_thread_stats {
	uint64_t busy_tsc;
	uint64_t idle_tsc;
};

struct spdk_spinlock {
	pthread_spinlock_t spinlock;
	struct spdk_thread *thread;
	struct spdk_spinlock_internal *internal;
	bool initialized;
	bool destroyed;
};

struct spdk_iobuf_opts {
	uint64_t small_pool_count;
	uint64_t large_pool_count;
	uint32_t small_bufsize;
	uint32_t large_bufsize;
	size_t opts_size;
	uint8_t	enable_numa;
};

struct spdk_iobuf_pool_stats {
	uint64_t	cache;
	uint64_t	main;
	uint64_t	retry;
};

struct spdk_iobuf_module_stats {
	struct spdk_iobuf_pool_stats	small_pool;
	struct spdk_iobuf_pool_stats	large_pool;
	const char			*module;
};

struct spdk_iobuf_entry {
	spdk_iobuf_get_cb		cb_fn;
	const void			*module;
	STAILQ_ENTRY(spdk_iobuf_entry)	stailq;
};

struct spdk_iobuf_pool_cache {
	struct spdk_ring		*pool;
	spdk_iobuf_buffer_stailq_t	cache;
	uint32_t			cache_count;
	uint32_t			cache_size;
	spdk_iobuf_entry_stailq_t	*queue;
	uint32_t			bufsize;
	struct spdk_iobuf_pool_stats	stats;
};

struct spdk_iobuf_node_cache {
	struct spdk_iobuf_pool_cache	small;
	struct spdk_iobuf_pool_cache	large;
};

struct spdk_iobuf_channel {
	const void			*module;
	struct spdk_io_channel		*parent;
	struct spdk_iobuf_node_cache	cache[SPDK_CONFIG_MAX_NUMA_NODES];
};

